    32  void Deserializer::deserializeNull(State& state) {
    33    if(state.caret->isAtText("null", true)){
    34      state.tree->setNull();
    35    } else {
    36      state.errorStack.push("[oatpp::json::Deserializer::deserializeNull()]: 'null' expected");
    37    }
    38  }
