    40  void Deserializer::deserializeNumber(State& state) {
    41    if (!Utils::findDecimalSeparatorInCurrentNumber(*state.caret)) {
    42      state.tree->setInteger(state.caret->parseInt());
    43    } else {
    44      state.tree->setFloat(state.caret->parseFloat64());
    45    }
    46  }
