    48  void Deserializer::deserializeBoolean(State& state) {
    49    if(state.caret->isAtText("true", true)) {
    50      state.tree->setPrimitive<bool>(true);
    51    } else if(state.caret->isAtText("false", true)) {
    52      state.tree->setPrimitive<bool>(false);
    53    } else {
    54      state.errorStack.push("[oatpp::json::Deserializer::deserializeBoolean()]: 'true' or 'false' expected");
    55    }
    56  }
